### 2.1 静态层绕过（LD_PRELOAD / 符号劫持）

```c
// hook_ptrace.c
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdarg.h>
#include <sys/ptrace.h>
#include <sys/syscall.h>
#include <unistd.h>

typedef long (*orig_ptrace_t)(int, pid_t, void*, void*);

static long my_ptrace(int request, pid_t pid, void *addr, void *data) {
    // 关键：首次 TRACEME 时伪造成功
    if (request == PTRACE_TRACEME) {
        // 返回 0 假装成功，实际不建立 trace 关系
        return 0;
    }
    // 其他请求走真实 syscall
    return syscall(SYS_ptrace, request, pid, addr, data);
}

// 通过 dlsym 链式 hook
```

